"""Command-line parser declarations."""
import argparse

DESCRIPTION='Command-line driver for the data layer (jef-data).\n\nSubcommands by phase (docs/DATA_LOADER_PLAN.md §4): D1 validate;\nD2 sync-actions; D4 load / adjust / import-csv / export; D5 differential;\nD6 universe; D7 sync (the whole configured universe in one command,\nordering ritual included - see jef.data.sync and src/jef/data/universe.toml).\n\nLike jef-binning, this is a thin argparse shell over importable functions;\nanything network- or Parquet-touching imports its module lazily so the core\ninstall (no [data] extra) can still run `jef-data validate`.'
HELPS={'validate': 'check a 7-column EOD CSV against docs/DATA_CONTRACT.md', 'sync-actions': 'fetch splits + dividends from EODHD into the actions store (needs EODHD_API_KEY; run BEFORE load)', 'load': 'fetch EOD history from EODHD into the Parquet store (incremental; needs EODHD_API_KEY; sync-actions first)', 'adjust': 're-derive main OHLCV from *_raw + stored splits (offline, idempotent; also the repair path)', 'import-csv': 'import a Yahoo 7-column CSV verbatim (price_basis=split_adjusted; offline)', 'export': 'store -> 7-column contract CSV (values identical; the bit-exact consumer path is jef.binning.loading.load_eod_store)', 'differential': 'tolerance-based comparison of two series (store vs store, or store vs a 7-column CSV) - the cross-provider gate; exit 1 on findings', 'sync': "run the whole universe's acquisition ritual from the config (per raw-basis symbol: sync-actions BEFORE load; tail-refresh reconcile once a series exists, crypto end-guarded at the previous UTC day; EODHD legs need EODHD_API_KEY)", 'status': 'read-only daily health: staleness, phantom-split scan, actions freshness, today-dated bars, price resolution, and the cross-venue close spread for multi-feed assets (offline, no key; exit 1 on any alert - the scheduler chain is sync && status)', 'universe': 'show the configured universe (assets, sources, thresholds; the D6 pilot by default)'}
OPTIONS={'validate': [('csv', {'help': 'CSV in the Yahoo 7-column schema'}), ('--min-rows', {'type': 'int', 'default': 1115, 'help': 'advisory minimum clean-row count'})], 'sync-actions': [('--symbol', {'required': True, 'help': 'e.g. AAPL.US'}), ('--store', {'default': 'data', 'help': 'store root (default: data/, gitignored)'}), ('--base-url', {'default': 'https://eodhd.com/api'})], 'load': [('--symbol', {'required': True}), ('--store', {'default': 'data'}), ('--from', {'help': 'YYYY-MM-DD (default: incremental from the last stored session)'}), ('--to', {}), ('--asset-type', {'choices': ['crypto', 'etf', 'stock'], 'help': 'required, except for EODHD .CC symbols (the crypto namespace is evidence); a ticker is not'}), ('--currency', {'default': 'USD'}), ('--base-url', {'default': 'https://eodhd.com/api'})], 'adjust': [('--symbol', {'required': True}), ('--exchange', {'default': 'eodhd'}), ('--store', {'default': 'data'})], 'import-csv': [('--csv', {'required': True}), ('--symbol', {'required': True}), ('--exchange', {'default': 'yahoo'}), ('--asset-type', {'required': True, 'choices': ['crypto', 'etf', 'stock'], 'help': 'required: a Yahoo CSV carries no instrument type'}), ('--currency', {'default': 'USD'}), ('--store', {'default': 'data'})], 'export': [('--symbol', {'required': True}), ('--exchange', {'default': 'eodhd'}), ('--output', {'required': True}), ('--store', {'default': 'data'})], 'differential': [('--a-symbol', {'required': True}), ('--a-exchange', {'default': 'eodhd'}), ('--b-symbol', {}), ('--b-exchange', {'default': 'yahoo'}), ('--b-csv', {'help': 'compare against a CSV instead of a stored series'}), ('--tolerance', {'type': 'float', 'default': 0.0001, 'help': 'relative tolerance per cell (default 1e-4)'}), ('--output', {'help': 'also write the report here'}), ('--store', {'default': 'data'})], 'sync': [('--universe', {'help': 'universe TOML (default: the packaged src/jef/data/universe.toml)'}), ('--store', {'help': "store root (default: the universe's defaults.store)"}), ('--asset', {'action': 'append', 'help': 'limit to this asset name (repeatable)'}), ('--provider', {'action': 'append', 'help': 'limit to this provider (repeatable), e.g. --provider eodhd where Binance is unreachable'}), ('--dry-run', {'action': 'store_true', 'help': 'plan from local store state only - no network, no key needed'}), ('--tail', {'type': 'int', 'default': 10, 'help': 'tail-refresh window in sessions, minimum 1 (docs/DATA_CONTRACT.md §7.2; default 10): newest-wins inside, frozen-first-seen outside'}), ('--force-actions', {'action': 'store_true', 'help': 'sync corporate actions even when fresh (override the once-per-UTC-day gate)'}), ('--base-url', {'help': 'EODHD base URL override'}), ('--summary-json', {'metavar': 'PATH', 'help': "write the per-leg results as JSON (the event ledger's stage_outcome diagnostics, Arc A A3(a)); written on red runs too"})], 'status': [('--universe', {'help': 'universe TOML (default: the packaged one)'}), ('--store', {'help': "store root (default: the universe's defaults.store)"}), ('--asset', {'action': 'append', 'help': 'limit to this asset name (repeatable)'}), ('--provider', {'action': 'append', 'help': 'limit to this provider (repeatable)'}), ('--staleness', {'type': 'int', 'default': 2, 'help': 'alert at this many missed expected sessions (docs/DATA_CONTRACT.md §7.4; default 2)'}), ('--jump-threshold', {'type': 'float', 'default': 0.4, 'help': 'phantom-split one-day |return| alert threshold (default 0.40)'}), ('--window', {'type': 'int', 'default': 10, 'help': 'newest sessions scanned for jumps, and for the cross-venue common session (default 10)'}), ('--resolution-window', {'type': 'int', 'default': 500, 'help': 'newest TRADED sessions measured for price resolution - zero-volume rows drop first, like the seam (docs/DATA_CONTRACT.md §7.8; default 500)'}), ('--resolution-k', {'type': 'float', 'default': 0.2, 'help': 'note a coarse quoting grid below this distinct-close/session ratio (default 0.20)'}), ('--flat-k', {'type': 'float', 'default': 0.25, 'help': 'note a coarse/frozen feed above this share of sessions whose close did not move (default 0.25)'}), ('--gap-k', {'type': 'int', 'default': 5, 'help': 'note a post-seam continuity gap at or above this many absent expected sessions (default 5, calibrated: the largest true US closure since 1962 measures 4 - 2001-09-10..17 - so the market itself never notes; a provider data hole does, however it is served)'}), ('--spread-threshold', {'type': 'float', 'default': 0.005, 'help': 'cross-venue close-spread WARN threshold for assets with 2+ live feeds (Arc X X1; default 0.005 = 0.5%%, calibrated on the committed fixtures - docs/CROSS_VENUE_PLAN.md)'}), ('--spread-alerts', {'action': 'store_true', 'help': "promote a cross-venue spread breach from a warning to an ALERT, so it joins the exit-1 contract (off by default: it compares a CROSS-CHECK leg, and exit 1 stops the venue's day before it publishes anything)"}), ('--json', {'action': 'store_true', 'help': 'machine-readable report instead of the table'})], 'universe': [('--universe', {'help': 'universe TOML (default: packaged)'})]}

def parser():
 p=argparse.ArgumentParser(prog='jef-data',description=DESCRIPTION)
 sub=p.add_subparsers(dest='command',required=True)
 for command,options in OPTIONS.items():
  s=sub.add_parser(command,help=HELPS[command])
  for arg,kw in options:
   kw=dict(kw)
   if 'type' in kw:kw['type']={'int':int,'float':float}[kw['type']]
   s.add_argument(arg,**kw)
 return p
